SELECT data.commit.collection::String AS event, count() AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT data.commit.collection::String AS event, count() AS count, uniqExact(data.did::String) AS users FROM bluesky WHERE data.kind::String = 'commit' AND data.commit.operation::String = 'create' GROUP BY event ORDER BY count DESC;
SELECT data.commit.collection::String AS event, toHour(fromUnixTimestamp64Micro(data.time_us::UInt64)) as hour_of_day, count() AS count FROM bluesky WHERE data.kind::String = 'commit' AND data.commit.operation::String = 'create' AND data.commit.collection::String in ['app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like'] GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data.did::String as user_id, min(fromUnixTimestamp64Micro(data.time_us::UInt64)) as first_post_ts FROM bluesky WHERE data.kind::String = 'commit' AND data.commit.operation::String = 'create' AND data.commit.collection::String = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data.did::String as user_id, date_diff( 'milliseconds', min(fromUnixTimestamp64Micro(data.time_us::UInt64)), max(fromUnixTimestamp64Micro(data.time_us::UInt64))) AS activity_span FROM bluesky WHERE data.kind::String = 'commit' AND data.commit.operation::String = 'create' AND data.commit.collection::String = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
